sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
i=json.loads((R/'inputs.json').read_bytes());node=json.loads((R/'independent-selectors.stdout.raw').read_bytes())
assert node['passed']==8
for phase in ['independent-selectors','runner-syntax']:assert json.loads((R/(phase+'.result.json')).read_bytes())['exit_code']==0
for phase in ['independent-path','independent-node-02']:assert json.loads((OLD/(phase+'.result.json')).read_bytes())['exit_code']==0
for name,pin in i['pins'].items():assert sha(R/'source'/name)==pin,name
def ref(p):return{'path':str(p),'sha256':sha(p),'bytes':p.stat().st_size}
