for directory in [OLD,R]:
 for f in sorted(directory.rglob('*')):
  if f.is_file() and f.name!='EVIDENCE-MANIFEST.json' and '__pycache__' not in f.parts:files.append({'path':f.relative_to(R.parent).as_posix(),'sha256':sha(f),'bytes':f.stat().st_size})
m=R/'EVIDENCE-MANIFEST.json';assert not m.exists();m.write_text(json.dumps({'root':str(R.parent),'files':files,'formal_increment':0},ensure_ascii=True,indent=2)+'\n',encoding='utf-8')
